import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry conv2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .s32 total_elements
)
{
    .reg .pred %p<20>;
    .reg .b32 %r<90>;
    .reg .b64 %rd<20>;
    .reg .f32 %f<10>;
    .shared .align 4 .f32 smem_input[4563];
    .shared .align 4 .f32 smem_weight[363];
    .shared .align 4 .f32 smem_bias[1];
    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [output_ptr];
    ld.param.s32 %r5, [total_elements];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;
    // block-tile coordinates: ctaid.x -> (tile_row,tile_col) over 7x7 tiles
    //                         ctaid.y -> (n, oc)
    mov.u32 %r10, %ctaid.x;
    mov.u32 %r11, %ctaid.y;
    mov.u32 %r12, %tid.x;
    div.s32 %r13, %r10, 7;      // tile_row
    rem.s32 %r14, %r10, 7;      // tile_col
    div.s32 %r15, %r11, 96;     // n
    rem.s32 %r16, %r11, 96;     // oc
    mul.lo.s32 %r17, %r13, 8;   // tile_oh_start
    mul.lo.s32 %r18, %r14, 8;   // tile_ow_start
    mul.lo.s32 %r19, %r17, 4;
    sub.s32 %r19, %r19, 2;      // ih_base
    mul.lo.s32 %r20, %r18, 4;
    sub.s32 %r20, %r20, 2;      // iw_base
    div.s32 %r21, %r12, 8;      // local_row
    rem.s32 %r22, %r12, 8;      // local_col
    add.s32 %r23, %r17, %r21;   // oh
    add.s32 %r24, %r18, %r22;   // ow
    setp.lt.s32 %p1, %r23, 55;
    setp.lt.s32 %p2, %r24, 55;
    and.pred %p3, %p1, %p2;     // valid_output
    // cooperative load of input tile (IC=3, 39x39) into shared memory
    mov.u32 %r30, %r12;
LOOP_LOAD_INPUT:
    setp.ge.s32 %p4, %r30, 4563;
    @%p4 bra END_LOAD_INPUT;
    div.s32 %r31, %r30, 1521;
    rem.s32 %r32, %r30, 1521;
    div.s32 %r33, %r32, 39;
    rem.s32 %r34, %r32, 39;
    add.s32 %r35, %r19, %r33;   // ih
    add.s32 %r36, %r20, %r34;   // iw
    setp.lt.s32 %p5, %r35, 0;
    setp.ge.s32 %p6, %r35, 224;
    or.pred %p7, %p5, %p6;
    setp.lt.s32 %p8, %r36, 0;
    setp.ge.s32 %p9, %r36, 224;
    or.pred %p10, %p8, %p9;
    or.pred %p11, %p7, %p10;
    mov.f32 %f1, 0f00000000;
    @%p11 bra SKIP_LOAD_VAL;
    mad.lo.s32 %r37, %r15, 3, %r31;
    mad.lo.s32 %r38, %r37, 224, %r35;
    mad.lo.s32 %r39, %r38, 224, %r36;
    mul.wide.s32 %rd10, %r39, 4;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.f32 %f1, [%rd11];
SKIP_LOAD_VAL:
    mov.u32 %r40, smem_input;
    mul.lo.s32 %r41, %r30, 4;
    add.u32 %r42, %r40, %r41;
    st.shared.f32 [%r42], %f1;
    add.s32 %r30, %r30, 64;
    bra LOOP_LOAD_INPUT;
END_LOAD_INPUT:
    // cooperative load of weight (IC=3,KH=11,KW=11) for this oc into shared memory
    mov.u32 %r50, %r12;
LOOP_LOAD_WEIGHT:
    setp.ge.s32 %p12, %r50, 363;
    @%p12 bra END_LOAD_WEIGHT;
    div.s32 %r51, %r50, 121;
    rem.s32 %r52, %r50, 121;
    div.s32 %r53, %r52, 11;
    rem.s32 %r54, %r52, 11;
    mad.lo.s32 %r55, %r16, 3, %r51;
    mad.lo.s32 %r56, %r55, 11, %r53;
    mad.lo.s32 %r57, %r56, 11, %r54;
    mul.wide.s32 %rd12, %r57, 4;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.f32 %f2, [%rd13];
    mov.u32 %r58, smem_weight;
    mul.lo.s32 %r59, %r50, 4;
    add.u32 %r60, %r58, %r59;
    st.shared.f32 [%r60], %f2;
    add.s32 %r50, %r50, 64;
    bra LOOP_LOAD_WEIGHT;
END_LOAD_WEIGHT:
    setp.ne.s32 %p13, %r12, 0;
    @%p13 bra SKIP_BIAS;
    mul.wide.s32 %rd14, %r16, 4;
    add.s64 %rd15, %rd3, %rd14;
    ld.global.f32 %f3, [%rd15];
    mov.u32 %r61, smem_bias;
    st.shared.f32 [%r61], %f3;
SKIP_BIAS:
    bar.sync 0;
    @!%p3 bra DONE;
    mov.u32 %r62, smem_bias;
    ld.shared.f32 %f4, [%r62];
    mov.u32 %r63, 0;           // ic
LOOP_IC2:
    setp.ge.s32 %p14, %r63, 3;
    @%p14 bra END_IC2;
    mov.u32 %r64, 0;           // kh
LOOP_KH2:
    setp.ge.s32 %p15, %r64, 11;
    @%p15 bra END_KH2;
    mad.lo.s32 %r65, %r21, 4, %r64;   // input tile row
    mov.u32 %r66, 0;           // kw
LOOP_KW2:
    setp.ge.s32 %p16, %r66, 11;
    @%p16 bra END_KW2;
    mad.lo.s32 %r67, %r22, 4, %r66;   // input tile col
    mad.lo.s32 %r68, %r63, 39, %r65;
    mad.lo.s32 %r69, %r68, 39, %r67;
    mov.u32 %r70, smem_input;
    mul.lo.s32 %r71, %r69, 4;
    add.u32 %r72, %r70, %r71;
    ld.shared.f32 %f5, [%r72];
    mad.lo.s32 %r73, %r63, 11, %r64;
    mad.lo.s32 %r74, %r73, 11, %r66;
    mov.u32 %r75, smem_weight;
    mul.lo.s32 %r76, %r74, 4;
    add.u32 %r77, %r75, %r76;
    ld.shared.f32 %f6, [%r77];
    fma.rn.f32 %f4, %f5, %f6, %f4;
    add.s32 %r66, %r66, 1;
    bra LOOP_KW2;
END_KW2:
    add.s32 %r64, %r64, 1;
    bra LOOP_KH2;
END_KH2:
    add.s32 %r63, %r63, 1;
    bra LOOP_IC2;
END_IC2:
    mad.lo.s32 %r78, %r15, 96, %r16;
    mad.lo.s32 %r79, %r78, 55, %r23;
    mad.lo.s32 %r80, %r79, 55, %r24;
    mul.wide.s32 %rd16, %r80, 4;
    add.s64 %rd17, %rd4, %rd16;
    st.global.f32 [%rd17], %f4;
DONE:
    ret;
